/* ===== Orchard Design System ===== */
:root {
  --text-primary: #1d1d1f;
  --text-secondary: #6e6e73;
  --text-tertiary: #86868b;
  --bg-primary: #ffffff;
  --bg-secondary: #f5f5f7;
  --bg-tertiary: #fafafa;
  --accent: #0066cc;
  --accent-hover: #004499;
  --border: #d2d2d7;
  --border-light: #e8e8ed;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.08);
  --shadow-xl: 0 16px 48px rgba(0,0,0,0.10);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', 'Segoe UI', sans-serif;
  --transition: 0.2s cubic-bezier(0.25, 0.1, 0.25, 1);
  --transition-slow: 0.4s cubic-bezier(0.25, 0.1, 0.25, 1);
  --max-width: 1200px;
  --header-height: 48px;
  --ribbon-height: 44px;
}

/* ===== Reset & Base ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
body {
  font-family: var(--font-stack);
  color: var(--text-primary);
  background: var(--bg-primary);
  line-height: 1.47059;
  font-size: 17px;
  font-weight: 400;
  min-height: 100vh;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }
ul, ol { list-style: none; }

/* ===== Ribbon Banner ===== */
.ribbon {
  background: #f5f5f7;
  text-align: center;
  padding: 12px 24px;
  font-size: 14px;
  line-height: 1.4;
  color: var(--text-primary);
}
.ribbon a {
  color: var(--accent);
  white-space: nowrap;
}
.ribbon a:hover { text-decoration: underline; }

/* ===== Global Header ===== */
.global-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,0.08);
  height: var(--header-height);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.header-logo {
  font-size: 21px;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}
.header-logo:hover { text-decoration: none; }
.header-nav { display: flex; gap: 28px; align-items: center; }
.header-nav a {
  font-size: 13px;
  color: var(--text-primary);
  font-weight: 400;
  letter-spacing: -0.01em;
  opacity: 0.85;
  transition: opacity var(--transition);
}
.header-nav a:hover { opacity: 1; text-decoration: none; }
.header-nav a.active { opacity: 1; }
.header-actions { display: flex; gap: 16px; align-items: center; }
.header-actions a {
  font-size: 13px;
  color: var(--text-primary);
  opacity: 0.7;
  transition: opacity var(--transition);
}
.header-actions a:hover { opacity: 1; text-decoration: none; }

@media (max-width: 768px) {
  .header-nav { gap: 16px; }
  .header-nav a { font-size: 12px; }
  .header-actions { display: none; }
}

/* ===== Section Commons ===== */
.section {
  padding: 80px 24px;
}
.section-light { background: var(--bg-primary); }
.section-gray { background: var(--bg-secondary); }
.section-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  margin-bottom: 8px;
}
.section-heading {
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.08349;
  margin-bottom: 12px;
}
.section-subheading {
  font-size: 21px;
  font-weight: 400;
  color: var(--text-secondary);
  letter-spacing: 0.011em;
  line-height: 1.381;
  max-width: 600px;
}
.section-header {
  text-align: center;
  margin-bottom: 48px;
}
.section-header .section-subheading {
  margin: 0 auto;
}
.section-header-left {
  text-align: left;
  margin-bottom: 40px;
}
.section-header-left .section-subheading { margin: 0; }

@media (max-width: 768px) {
  .section { padding: 48px 16px; }
  .section-heading { font-size: 32px; }
  .section-subheading { font-size: 17px; }
  .section-header { margin-bottom: 32px; }
}

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 11px 21px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.01em;
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--accent);
  color: #fff;
}
.btn-primary:hover {
  background: var(--accent-hover);
  text-decoration: none;
}
.btn-outline {
  border: 1px solid var(--accent);
  color: var(--accent);
  background: transparent;
}
.btn-outline:hover {
  background: var(--accent);
  color: #fff;
  text-decoration: none;
}
.btn-ghost {
  color: var(--accent);
}
.btn-ghost:hover {
  text-decoration: underline;
  background: none;
}
.btn-group { display: flex; gap: 16px; flex-wrap: wrap; align-items: center; }

/* ===== Product Icon Bar ===== */
.product-icon-bar {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 16px 0;
}
.product-icon-bar::-webkit-scrollbar { display: none; }
.product-icon-list {
  display: flex;
  gap: 32px;
  justify-content: center;
  min-width: max-content;
  padding: 0 24px;
}
.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
  transition: all var(--transition);
  min-width: 64px;
}
.product-icon-item:hover { color: var(--accent); text-decoration: none; }
.product-icon-item .icon-placeholder {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

/* ===== Carousel System ===== */
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 40px;
}
.carousel-container {
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  display: flex;
  gap: 20px;
  padding: 4px 0 20px;
}
.carousel-container::-webkit-scrollbar { display: none; }
.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: var(--radius-full);
  background: rgba(0,0,0,0.04);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  z-index: 10;
  transition: all var(--transition);
  border: 1px solid var(--border-light);
}
.carousel-arrow:hover { background: rgba(0,0,0,0.08); }
.carousel-arrow-left { left: 0; }
.carousel-arrow-right { right: 0; }
.carousel-arrow:disabled { opacity: 0.3; cursor: default; }

@media (max-width: 768px) {
  .carousel-wrapper { padding: 0 8px; }
  .carousel-arrow { display: none; }
}

/* ===== Product Card ===== */
.product-card {
  flex: 0 0 280px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}
.product-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.product-card-image {
  width: 100%;
  height: 200px;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 64px;
  position: relative;
  overflow: hidden;
}
.product-card-body {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-card-badge {
  font-size: 11px;
  font-weight: 600;
  color: #bf4800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.product-card-name {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.235;
}
.product-card-tagline {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.4;
  flex: 1;
}
.product-card-price {
  font-size: 15px;
  font-weight: 500;
  color: var(--text-primary);
}
.product-card-monthly {
  font-size: 13px;
  color: var(--text-secondary);
}
.product-card-extra {
  font-size: 12px;
  color: var(--text-tertiary);
}

/* Card size variants */
.product-card-sm { flex: 0 0 240px; }
.product-card-sm .product-card-image { height: 170px; font-size: 48px; }
.product-card-lg { flex: 0 0 320px; }
.product-card-lg .product-card-image { height: 240px; font-size: 72px; }

@media (max-width: 768px) {
  .product-card { flex: 0 0 240px; }
  .product-card-sm { flex: 0 0 200px; }
  .product-card-lg { flex: 0 0 280px; }
}

/* ===== Product Card Horizontal ===== */
.product-card-horizontal {
  flex: 0 0 360px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  padding: 24px;
  display: flex;
  gap: 20px;
  align-items: center;
  transition: all var(--transition);
}
.product-card-horizontal:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}
.product-card-horizontal .pch-image {
  width: 80px;
  height: 80px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 36px;
}
.product-card-horizontal .pch-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.pch-name { font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.pch-price { font-size: 14px; font-weight: 500; }
.pch-note { font-size: 12px; color: var(--text-tertiary); }

@media (max-width: 768px) {
  .product-card-horizontal { flex: 0 0 300px; }
}

/* ===== Hero Product Showcase (Homepage) ===== */
.hero-store {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--bg-primary);
}
.hero-store-label {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 4px;
}
.hero-store h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.07143;
  margin-bottom: 8px;
}
.hero-store-subtitle {
  font-size: 24px;
  font-weight: 400;
  color: var(--text-secondary);
  letter-spacing: 0.01em;
  margin-bottom: 28px;
}

@media (max-width: 768px) {
  .hero-store h1 { font-size: 36px; }
  .hero-store-subtitle { font-size: 17px; }
}

/* ===== Product Grid (Homepage) ===== */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.product-tile {
  position: relative;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 48px 24px 40px;
  transition: all var(--transition);
}
.product-tile:hover {
  box-shadow: var(--shadow-lg);
}
.product-tile.tile-full {
  grid-column: 1 / -1;
}
.product-tile-image {
  width: 100%;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 96px;
  margin-bottom: 16px;
}
.product-tile-headline {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.125;
  margin-bottom: 4px;
}
.product-tile-tagline {
  font-size: 17px;
  color: var(--text-secondary);
  margin-bottom: 20px;
  max-width: 360px;
}

/* Tile color variants */
.tile-warm { background: linear-gradient(135deg, #faf7f2 0%, #f5ede0 100%); }
.tile-cool { background: linear-gradient(135deg, #f2f5f8 0%, #e5edf5 100%); }
.tile-dark { background: #1d1d1f; color: #f5f5f7; }
.tile-dark .product-tile-tagline { color: #a1a1a6; }
.tile-dark .product-tile-headline { color: #f5f5f7; }

@media (max-width: 768px) {
  .product-grid { grid-template-columns: 1fr; }
  .product-tile { min-height: 380px; }
  .product-tile-headline { font-size: 24px; }
  .product-tile-image { height: 160px; font-size: 64px; }
}

/* ===== Entertainment Tabs ===== */
.entertainment-section {
  background: var(--bg-secondary);
  padding: 80px 0;
}
.ent-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 32px;
  flex-wrap: wrap;
}
.ent-tab {
  padding: 10px 24px;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}
.ent-tab:hover { color: var(--text-primary); background: rgba(0,0,0,0.04); }
.ent-tab.active {
  background: var(--text-primary);
  color: #fff;
}
.ent-panels { position: relative; max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }
.ent-panel { display: none; }
.ent-panel.active { display: block; }
.ent-panel-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.ent-card {
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.ent-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.ent-card-image {
  width: 100%;
  height: 180px;
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card-body { padding: 16px; }
.ent-card-title { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.ent-card-subtitle { font-size: 13px; color: var(--text-secondary); margin-bottom: 12px; }
.ent-card-cta { font-size: 13px; font-weight: 500; color: var(--accent); }

@media (max-width: 768px) {
  .ent-panel-grid { grid-template-columns: repeat(2, 1fr); }
}

/* ===== Category Hero ===== */
.category-hero {
  text-align: center;
  padding: 60px 24px 20px;
  background: var(--bg-primary);
}
.category-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.07143;
}

/* ===== Sticky Section Nav ===== */
.section-nav {
  position: sticky;
  top: var(--header-height);
  z-index: 90;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--border-light);
}
.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  gap: 0;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-item {
  padding: 14px 20px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.section-nav-item:hover { color: var(--text-primary); text-decoration: none; }
.section-nav-item.active {
  color: var(--text-primary);
  border-bottom-color: var(--text-primary);
}

/* ===== Help & Support Cards ===== */
.help-card {
  flex: 0 0 300px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
}
.help-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.help-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  margin-bottom: 16px;
}
.help-card-title {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  margin-bottom: 8px;
}
.help-card-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ===== Store Difference / Savings Cards ===== */
.diff-card {
  flex: 0 0 260px;
  scroll-snap-align: start;
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition);
  text-align: center;
}
.diff-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
.diff-card-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-full);
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 26px;
  margin: 0 auto 16px;
}
.diff-card-title { font-size: 15px; font-weight: 600; margin-bottom: 6px; }
.diff-card-desc { font-size: 13px; color: var(--text-secondary); line-height: 1.5; }

/* ===== Brand Collab ===== */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 80px 24px;
  text-align: center;
}
.collab-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  margin-bottom: 24px;
}
.collab-logo {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.collab-x { font-size: 24px; color: var(--text-tertiary); }
.collab-desc {
  max-width: 500px;
  margin: 0 auto 24px;
  font-size: 17px;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ===== Quick Links ===== */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 48px 24px;
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}
.quick-link {
  padding: 12px 24px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
  background: var(--bg-secondary);
  border-radius: var(--radius-full);
  transition: all var(--transition);
}
.quick-link:hover { background: #e8e8ed; text-decoration: none; }

/* ===== Promo Banner ===== */
.promo-banner {
  max-width: var(--max-width);
  margin: 40px auto;
  padding: 0 24px;
  text-align: center;
}
.promo-text {
  font-size: 17px;
  font-weight: 500;
  color: var(--text-primary);
  line-height: 1.5;
}

/* ===== Shopping Guides / Ways to Save Lists ===== */
.guide-list {
  max-width: var(--max-width);
  margin: 0 auto;
}
.guide-item {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 20px 0;
  border-bottom: 1px solid var(--border-light);
}
.guide-item:last-child { border-bottom: none; }
.guide-item-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  flex-shrink: 0;
}
.guide-item-content h4 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
}
.guide-item-content p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}
.guide-item-content a {
  font-size: 14px;
  font-weight: 500;
  color: var(--accent);
}

/* ===== Footer ===== */
.footer {
  background: var(--bg-secondary);
  padding: 40px 24px 24px;
  font-size: 12px;
  color: var(--text-secondary);
}
.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}
.footer-notes {
  padding-bottom: 20px;
  border-bottom: 1px solid var(--border-light);
  margin-bottom: 24px;
  line-height: 1.6;
  font-size: 12px;
  color: var(--text-tertiary);
}
.footer-notes p { margin-bottom: 8px; }
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 24px;
}
