/* ===== Hero Product Showcase (Homepage) ===== */
.hero-store {
  text-align: center;
  padding: 60px 24px 40px;
  background: var(--bg-primary);
}
.hero-store-label {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-secondary);
  margin-bottom: 4px;
}
.hero-store h1 {
