  font-weight: 400;
  color: var(--text-secondary);
  letter-spacing: 0.01em;
  margin-bottom: 28px;
}

@media (max-width: 768px) {
  .hero-store h1 { font-size: 36px; }
  .hero-store-subtitle { font-size: 17px; }
