/* ===== Product Grid (Homepage) ===== */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px 80px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}
.product-tile {
  position: relative;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  min-height: 480px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 48px 24px 40px;
  transition: all var(--transition);
}
.product-tile:hover {
  box-shadow: var(--shadow-lg);
}
.product-tile.tile-full {
  grid-column: 1 / -1;
}
.product-tile-image {
  width: 100%;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 96px;
  margin-bottom: 16px;
}
.product-tile-headline {
  font-size: 32px;
  font-weight: 700;
  letter-spacing: -0.015em;
  line-height: 1.125;
  margin-bottom: 4px;
}
.product-tile-tagline {
  font-size: 17px;
  color: var(--text-secondary);
  margin-bottom: 20px;
  max-width: 360px;
}

/* Tile color variants */
.tile-warm { background: linear-gradient(135deg, #faf7f2 0%, #f5ede0 100%); }
.tile-cool { background: linear-gradient(135deg, #f2f5f8 0%, #e5edf5 100%); }
.tile-dark { background: #1d1d1f; color: #f5f5f7; }
.tile-dark .product-tile-tagline { color: #a1a1a6; }
.tile-dark .product-tile-headline { color: #f5f5f7; }

